   501	static int dmic_open_output(struct dmic_runtime *rt,
   502	                            const struct dmic_options *opts) {
   503	  int ret;
   504	
   505	  rt->fd = -1;
   506	  if (opts->outfile == NULL) {
   507	    return 0;
   508	  }
   509	
   510	  rt->fd = open(opts->outfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
   511	  if (rt->fd < 0) {
   512	    ret = -errno;
   513	    fprintf(stderr, "dmic: open %s failed: %d\n", opts->outfile, -ret);
   514	    return ret;
   515	  }
   516	
   517	  if (opts->wav) {
   518	    ret = dmic_write_wav_header(rt->fd, opts, 0);
   519	    if (ret < 0) {
   520	      fprintf(stderr, "dmic: write wav header failed: %d\n", -ret);
   521	      return ret;
   522	    }
   523	  }
   524	
   525	  return 0;
   526	}
