   528	static int dmic_finish_output(struct dmic_runtime *rt,
   529	                              const struct dmic_options *opts) {
   530	  int ret;
   531	
   532	  if (rt->fd < 0) {
   533	    return 0;
   534	  }
   535	
   536	  if (opts->wav) {
   537	    if (lseek(rt->fd, 0, SEEK_SET) < 0) {
   538	      ret = -errno;
   539	      fprintf(stderr, "dmic: seek wav header failed: %d\n", -ret);
   540	      return ret;
   541	    }
   542	
   543	    ret = dmic_write_wav_header(rt->fd, opts, (uint32_t)rt->data_bytes);
   544	    if (ret < 0) {
   545	      fprintf(stderr, "dmic: update wav header failed: %d\n", -ret);
   546	      return ret;
   547	    }
