   553	static int dmic_handle_period(struct dmic_runtime *rt,
   554	                              const struct dmic_options *opts,
   555	                              unsigned int slot) {
   556	  uint8_t *period = rt->buffer + slot * rt->period_bytes;
   557	  int ret;
   558	
   559	  up_invalidate_dcache((uintptr_t)period,
   560	                       (uintptr_t)period + rt->period_bytes);
   561	
   562	  if (rt->fd >= 0) {
   563	    ret = dmic_write_all(rt->fd, period, rt->period_bytes);
   564	    if (ret < 0) {
   565	      fprintf(stderr, "dmic: write %s failed: %d\n", opts->outfile, -ret);
   566	      return ret;
   567	    }
   568	  }
   569	
   570	  dmic_process_period(rt, period);
   571	  rt->data_bytes += rt->period_bytes;
   572	  rt->processed_periods++;
   573	  return 0;
   574	}
