   576	static int dmic_capture_wait(struct dmic_runtime *rt,
   577	                             const struct dmic_options *opts,
   578	                             uint32_t target_periods) {
   579	  uint32_t done[DMIC_BUFFER_PERIODS] = {0};
   580	  uint32_t period_events = 0;
   581	  uint32_t idle_us = 0;
   582	
   583	  while ((target_periods == 0 || period_events < target_periods) &&
   584	         !g_dmic_stop) {
   585	    bool progressed = false;
   586	
   587	    for (unsigned int slot = 0; slot < DMIC_BUFFER_PERIODS; slot++) {
   588	      uint32_t ready = rt->ready[slot];
   589	      uint32_t delta = ready - done[slot];
   590	
   591	      if (delta == 0) {
   592	        continue;
   593	      }
   594	
   595	      if (delta > 1) {
   596	        uint32_t skipped = delta - 1;
   597	        rt->lost_periods += skipped;
   598	        period_events += skipped;
   599	        done[slot] = ready - 1;
   600	      }
   601	
   602	      if (target_periods != 0 && period_events >= target_periods) {
   603	        break;
   604	      }
   605	
   606	      if (dmic_handle_period(rt, opts, slot) < 0) {
   607	        return -EIO;
   608	      }
   609	
   610	      done[slot] = ready;
   611	      period_events++;
   612	      progressed = true;
   613	    }
   614	
   615	    if (progressed) {
   616	      idle_us = 0;
   617	      continue;
   618	    }
   619	
   620	    usleep(DMIC_POLL_US);
   621	    idle_us += DMIC_POLL_US;
   622	    if (idle_us >= DMIC_NO_DATA_TIMEOUT_US) {
   623	      fprintf(stderr, "dmic: timeout waiting for DMA period interrupt\n");
   624	      dmic_dump_runtime_regs(rt, "timeout");
   625	      return -ETIMEDOUT;
   626	    }
   627	  }
   628	
   629	  return 0;
   630	}
