   632	static int dmic_validate_options(struct dmic_options *opts) {
   633	  uint32_t frame_bytes = dmic_frame_bytes(opts->channels);
   634	
   635	  if (!dmic_valid_rate(opts->samplerate)) {
   636	    fprintf(stderr, "dmic: unsupported samplerate %" PRIu32 "\n",
   637	            opts->samplerate);
   638	    return -EINVAL;
   639	  }
   640	
   641	  if (opts->channels != 1 && opts->channels != 2) {
   642	    fprintf(stderr, "dmic: channels must be 1 or 2\n");
   643	    return -EINVAL;
   644	  }
   645	
   646	  if (opts->period_bytes == 0) {
   647	    opts->period_bytes = DMIC_DEFAULT_PERIOD_BYTES;
   648	  }
   649	
   650	  if ((opts->period_bytes % CACHE_LINE_SIZE) != 0 ||
   651	      (opts->period_bytes % frame_bytes) != 0) {
   652	    fprintf(stderr,
   653	            "dmic: period_bytes must align to %u and frame size %" PRIu32 "\n",
   654	            CACHE_LINE_SIZE, frame_bytes);
   655	    return -EINVAL;
   656	  }
   657	
   658	  if (opts->outfile != NULL && dmic_path_is_wav(opts->outfile)) {
   659	    opts->wav = true;
   660	  }
   661	
   662	  return 0;
   663	}
   664	
   665	static int dmic_parse_args(int argc, char *argv[], struct dmic_options *opts) {
   666	  int ch;
   667	
   668	  opts->samplerate = DMIC_DEFAULT_RATE;
   669	  opts->channels = DMIC_DEFAULT_CHANNELS;
   670	  opts->seconds = DMIC_DEFAULT_SECONDS;
   671	  opts->period_bytes = DMIC_DEFAULT_PERIOD_BYTES;
   672	  opts->outfile = NULL;
   673	  opts->wav = false;
   674	
   675	  if (argc > 1 && strcmp(argv[1], "start") == 0) {
   676	    argc--;
   677	    argv++;
   678	  }
   679	
   680	  optind = 1;
   681	  while ((ch = getopt(argc, argv, "hr:c:t:p:o:w")) != -1) {
   682	    uint32_t value;
   683	
   684	    switch (ch) {
   685	    case 'h':
   686	      dmic_usage();
   687	      return 1;
   688	
   689	    case 'r':
   690	      if (dmic_parse_u32(optarg, &opts->samplerate) < 0) {
   691	        return -EINVAL;
   692	      }
   693	      break;
   694	
   695	    case 'c':
   696	      if (dmic_parse_u32(optarg, &value) < 0 || value > UINT8_MAX) {
   697	        return -EINVAL;
   698	      }
   699	      opts->channels = (uint8_t)value;
   700	      break;
   701	
   702	    case 't':
   703	      if (dmic_parse_u32(optarg, &opts->seconds) < 0) {
   704	        return -EINVAL;
   705	      }
   706	      break;
   707	
   708	    case 'p':
   709	      if (dmic_parse_u32(optarg, &opts->period_bytes) < 0) {
   710	        return -EINVAL;
   711	      }
   712	      break;
   713	
   714	    case 'o':
   715	      opts->outfile = optarg;
   716	      break;
   717	
   718	    case 'w':
   719	      opts->wav = true;
   720	      break;
   721	
   722	    default:
   723	      return -EINVAL;
   724	    }
   725	  }
   726	
   727	  if (optind < argc) {
   728	    if (dmic_parse_u32(argv[optind], &opts->seconds) == 0) {
   729	      optind++;
   730	    }
   731	  }
   732	
   733	  if (optind < argc) {
   734	    opts->outfile = argv[optind++];
   735	  }
   736	
   737	  if (optind < argc) {
   738	    return -EINVAL;
   739	  }
   740	
   741	  if (opts->wav && opts->outfile == NULL) {
   742	    opts->outfile = "/data/dmic.wav";
   743	  }
   744	
   745	  return dmic_validate_options(opts);
   746	}
   747	
   748	static uint32_t dmic_target_periods(const struct dmic_options *opts) {
   749	  uint64_t target_bytes;
   750	
   751	  if (opts->seconds == 0) {
   752	    return 0;
   753	  }
   754	
   755	  target_bytes = (uint64_t)opts->samplerate * dmic_frame_bytes(opts->channels) *
   756	                 opts->seconds;
   757	  return (uint32_t)((target_bytes + opts->period_bytes - 1) /
   758	                    opts->period_bytes);
   759	}
