   761	static int dmic_start_capture(const struct dmic_options *opts) {
   762	  struct dmic_runtime rt;
   763	  uint32_t target_periods;
   764	  int ret;
   765	
   766	  memset(&rt, 0, sizeof(rt));
   767	  rt.fd = -1;
   768	  rt.channels = opts->channels;
   769	  rt.period_bytes = opts->period_bytes;
   770	  rt.buffer_bytes = opts->period_bytes * DMIC_BUFFER_PERIODS;
   771	  rt.wav = opts->wav;
   772	  dmic_stats_init(&rt);
   773	
   774	  rt.buffer = memalign(CACHE_LINE_SIZE, rt.buffer_bytes);
   775	  if (rt.buffer == NULL) {
   776	    fprintf(stderr, "dmic: allocate %" PRIu32 " bytes failed\n",
   777	            rt.buffer_bytes);
   778	    return -ENOMEM;
   779	  }
   780	
   781	  memset(rt.buffer, 0, rt.buffer_bytes);
   782	  up_invalidate_dcache((uintptr_t)rt.buffer,
   783	                       (uintptr_t)rt.buffer + rt.buffer_bytes);
   784	
   785	  ret = dmic_open_output(&rt, opts);
   786	  if (ret < 0) {
   787	    goto out;
