/* ── Entropy source ──────────────────────────────────────────── */

static int asr_entropy_func(void* data, unsigned char* output, size_t len)
{
    (void)data;
    int fd = open("/dev/urandom", O_RDONLY);

    if (fd < 0) {
        fd = open("/dev/random", O_RDONLY);
    }

    if (fd >= 0) {
        ssize_t n = read(fd, output, len);

        close(fd);
        if (n == (ssize_t)len) {
            return 0;
        }
    }

    /* Fallback: time-based PRNG for QEMU/sim environments */
    static unsigned int seed;

    if (seed == 0) {
        seed = (unsigned int)time(NULL);
    }
    for (size_t i = 0; i < len; i++) {
        output[i] = (unsigned char)(rand_r(&seed) & 0xFF);
    }
    return 0;
}

