    54	
    55	static int resp_buf_init(resp_buf_t* rb, size_t initial_cap)
    56	{
    57	    rb->data = calloc(1, initial_cap);
    58	    if (!rb->data)
    59	        return ERROR;
    60	    rb->len = 0;
    61	    rb->cap = initial_cap;
    62	    return OK;
