    64	
    65	static int resp_buf_append(resp_buf_t* rb, const char* data, size_t len)
    66	{
    67	    while (rb->len + len >= rb->cap) {
    68	        size_t new_cap = rb->cap * 2;
    69	        if (new_cap > VELACLAW_LLM_MAX_RESP_SIZE) {
    70	            syslog(LOG_ERR, "llm: resp_buf exceeded %d limit\n",
    71	                VELACLAW_LLM_MAX_RESP_SIZE);
    72	            return ERROR;
