    74	        char* tmp = realloc(rb->data, new_cap);
    75	        if (!tmp)
    76	            return ERROR;
    77	        rb->data = tmp;
    78	        rb->cap = new_cap;
    79	    }
    80	    memcpy(rb->data + rb->len, data, len);
    81	    rb->len += len;
    82	    rb->data[rb->len] = '\0';
    83	    return OK;
    84	}
