   300	/* ── Complexity estimation ────────────────────────────────── */
   301	
   302	llm_complexity_t llm_router_estimate_complexity(const char* prompt, size_t prompt_len)
   303	{
   304	    if (!prompt || prompt_len == 0) {
   305	        return LLM_COMPLEXITY_SIMPLE;
   306	    }
   307	
   308	    int score = 0;
   309	
   310	    /* Length-based scoring: rough token estimate (1 token ~ 4 chars) */
   311	    size_t est_tokens = prompt_len / 4;
   312	    if (est_tokens > 200) {
   313	        score += 3;
   314	    } else if (est_tokens > 50) {
   315	        score += 1;
   316	    }
   317	
   318	    /* Question mark count — multiple questions suggest complexity */
   319	    int qmarks = 0;
   320	    for (size_t i = 0; i < prompt_len; i++) {
   321	        if (prompt[i] == '?' || (i + 2 < prompt_len && (unsigned char)prompt[i] == 0xEF && (unsigned char)prompt[i + 1] == 0xBC && (unsigned char)prompt[i + 2] == 0x9F)) {
   322	            qmarks++;
   323	        }
   324	    }
   325	    if (qmarks >= 3) {
   326	        score += 2;
   327	    } else if (qmarks >= 1) {
   328	        score += 1;
   329	    }
   330	
   331	    /* Code block detection (``` or indented code) */
   332	    if (strstr(prompt, "```") != NULL) {
   333	        score += 3;
   334	    }
   335	
   336	    /* Complex keyword detection */
   337	    if (contains_keyword(prompt, s_complex_keywords)) {
   338	        score += 2;
   339	    }
   340	
   341	    /* Simple keyword shortcut — only if nothing else triggers */
   342	    if (score == 0 && prompt_len < 50
   343	        && contains_keyword(prompt, s_simple_keywords)) {
   344	        return LLM_COMPLEXITY_SIMPLE;
   345	    }
   346	
   347	    /* Score thresholds */
   348	    if (score >= 4) {
   349	        return LLM_COMPLEXITY_COMPLEX;
   350	    } else if (score >= 2) {
   351	        return LLM_COMPLEXITY_MEDIUM;
   352	    }
   353	    return LLM_COMPLEXITY_SIMPLE;
   354	}
