    pthread_mutex_lock(&s_voice.lock);
    s_voice.asr_stream = stream;
    pthread_mutex_unlock(&s_voice.lock);

    syslog(LOG_INFO, "[%s] recording thread exiting\n", TAG);
    return NULL;
