  char *endptr;
  unsigned long parsed;

  if (text == NULL || value == NULL) {
    return -EINVAL;
  }

  errno = 0;
  parsed = strtoul(text, &endptr, 0);
  if (errno != 0 || endptr == text || *endptr != '\0' ||
      parsed > UINT32_MAX) {
    return -EINVAL;
  }

  *value = (uint32_t)parsed;
  return 0;
}

