  rt->fd = -1;
  if (opts->outfile == NULL) {
    return 0;
  }

  rt->fd = open(opts->outfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (rt->fd < 0) {
    ret = -errno;
    fprintf(stderr, "dmic: open %s failed: %d\n", opts->outfile, -ret);
    return ret;
