+          (uintptr_t)(cap->dma_buf + slot * cap->period_bytes),
+          (uintptr_t)(cap->dma_buf + (slot + 1) * cap->period_bytes));
+      memcpy(cap->read_buf,
+             cap->dma_buf + slot * cap->period_bytes,
+             cap->period_bytes);
+      cap->consumed[slot] = consumed + 1;
+      cap->next_read_slot++;
+      continue;
+    }
