+      syslog(LOG_ERR, "[%s] timeout waiting for DMIC period\n", TAG);
+      return copied > 0 ? (int)copied : -ETIMEDOUT;
+    }
+
+    usleep(CAP_POLL_US);
+    waited_us += CAP_POLL_US;
+  }
+
+  return (int)copied;
+}
