/*
 * audio_playback.c - Raw PCM playback through NxPlayer.
 *
 * TTS returns raw PCM. NxPlayer already knows how to configure the board
 * audio lower-half and waits for the playback thread when released, which
 * avoids deleting the temporary file while the driver is still consuming it.
 */

#include "voice/audio_playback.h"
#include "velaclaw_config.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
