static const char *TAG = "audio_pb";

#define PB_TMP_PATH VELACLAW_DATA_DIR "/tts_play.pcm"

struct audio_playback
{
  int tmp_fd;
  size_t total_written;
  unsigned int sample_rate;
  unsigned int channels;
  unsigned int bits_per_sample;
  int write_error;
#ifdef CONFIG_NXPLAYER_INCLUDE_PREFERRED_DEVICE
  char dev_path[128];
#endif
};

audio_playback_t *audio_playback_open(const char *dev_path,
                                      unsigned int sample_rate,
                                      unsigned int channels,
                                      unsigned int bits_per_sample)
{
  audio_playback_t *pb;

  if (sample_rate == 0 || (channels != 1 && channels != 2) ||
      bits_per_sample != 16) {
    return NULL;
  }

  pb = calloc(1, sizeof(*pb));
  if (pb == NULL) {
    return NULL;
  }

  pb->tmp_fd = open(PB_TMP_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (pb->tmp_fd < 0) {
    syslog(LOG_ERR, "[%s] cannot create %s: %d\n",
           TAG, PB_TMP_PATH, errno);
    free(pb);
    return NULL;
  }

  pb->sample_rate = sample_rate;
  pb->channels = channels;
  pb->bits_per_sample = bits_per_sample;
#ifdef CONFIG_NXPLAYER_INCLUDE_PREFERRED_DEVICE
  if (dev_path != NULL) {
    snprintf(pb->dev_path, sizeof(pb->dev_path), "%s", dev_path);
  }
#else
  (void)dev_path;
#endif

  syslog(LOG_INFO, "[%s] opened (%uHz %uch %ubit)\n",
         TAG, sample_rate, channels, bits_per_sample);
  return pb;
}

int audio_playback_write(audio_playback_t *pb,
                         const void *buf, size_t len)
{
  const unsigned char *src;
  size_t off = 0;

  if (pb == NULL || pb->tmp_fd < 0 || buf == NULL || len == 0) {
    return -EINVAL;
  }

  src = (const unsigned char *)buf;
  while (off < len) {
    ssize_t n = write(pb->tmp_fd, src + off, len - off);
    if (n < 0) {
      if (errno == EINTR) {
        continue;
      }
      pb->write_error = errno == 0 ? EIO : errno;
      return -pb->write_error;
    }
    if (n == 0) {
      pb->write_error = EIO;
      return -EIO;
    }
    off += (size_t)n;
  }

  pb->total_written += off;
  return (int)off;
}

static void audio_playback_close_legacy(audio_playback_t *pb)
{
#ifndef CONFIG_SYSTEM_NXPLAYER
  char url[256];
  char opts[128];
  void *player;
  int ret;

  snprintf(url, sizeof(url), "file://%s", PB_TMP_PATH);
  snprintf(opts, sizeof(opts),
           "format=s%ule:sample_rate=%u:ch_layout=%s",
           pb->bits_per_sample, pb->sample_rate,
           pb->channels == 1 ? "mono" : "stereo");

  player = media_player_open(MEDIA_STREAM_MUSIC);
  if (player == NULL) {
    syslog(LOG_ERR, "[%s] media_player_open failed\n", TAG);
    return;
  }

  ret = media_player_prepare(player, url, opts);
  if (ret < 0) {
    syslog(LOG_ERR, "[%s] media_player_prepare failed: %d\n", TAG, ret);
    media_player_close(player, 0);
    return;
  }

  ret = media_player_start(player);
  if (ret < 0) {
    syslog(LOG_ERR, "[%s] media_player_start failed: %d\n", TAG, ret);
    media_player_close(player, 0);
    return;
  }

  /* Legacy media_player has no reliable completion primitive. */
  if (pb->sample_rate > 0 && pb->channels > 0 &&
      pb->bits_per_sample >= 8) {
    uint64_t bytes_per_second =
        (uint64_t)pb->sample_rate * pb->channels *
        (pb->bits_per_sample / 8);
    unsigned int duration_ms =
        (unsigned int)(pb->total_written * 1000 / bytes_per_second) + 500;
    usleep((useconds_t)duration_ms * 1000);
  }

  media_player_close(player, 0);
#else
  (void)pb;
#endif
}

void audio_playback_close(audio_playback_t *pb)
{
  if (pb == NULL) {
    return;
  }

  if (pb->tmp_fd >= 0) {
    close(pb->tmp_fd);
    pb->tmp_fd = -1;
  }

  if (pb->write_error != 0) {
    syslog(LOG_ERR, "[%s] PCM write failed: %d\n",
           TAG, pb->write_error);
    goto out;
  }

  if (pb->total_written == 0) {
    syslog(LOG_WARNING, "[%s] no PCM data to play\n", TAG);
    goto out;
  }

#ifdef CONFIG_SYSTEM_NXPLAYER
  {
    struct nxplayer_s *player = nxplayer_create();
    int ret;

    if (player == NULL) {
      syslog(LOG_ERR, "[%s] nxplayer_create failed\n", TAG);
      goto out;
    }

#ifdef CONFIG_NXPLAYER_INCLUDE_PREFERRED_DEVICE
    ret = nxplayer_setdevice(player, pb->dev_path[0] != '\0'
                                      ? pb->dev_path
                                      : VELACLAW_AUDIO_PLAYBACK_DEV);
    if (ret < 0) {
      syslog(LOG_WARNING, "[%s] nxplayer_setdevice failed: %d\n",
             TAG, ret);
    }
#endif

    ret = nxplayer_playraw(player, PB_TMP_PATH, AUDIO_FMT_PCM,
                           AUDIO_FMT_UNDEF, (uint8_t)pb->channels,
                           (uint8_t)pb->bits_per_sample, pb->sample_rate, 0);
    if (ret < 0) {
      syslog(LOG_ERR, "[%s] nxplayer_playraw failed: %d\n", TAG, ret);
      nxplayer_release(player);
      goto out;
    }

    syslog(LOG_INFO, "[%s] playing %s (%zu bytes)\n",
           TAG, PB_TMP_PATH, pb->total_written);
    nxplayer_release(player);
    syslog(LOG_INFO, "[%s] playback done\n", TAG);
  }
#else
  audio_playback_close_legacy(pb);
#endif

out:
  unlink(PB_TMP_PATH);
  free(pb);
}
    return 0;
}

int voice_channel_stop(void)
{
    pthread_mutex_lock(&s_voice.lock);
    if (s_voice.state != VOICE_RECORDING) {
        pthread_mutex_unlock(&s_voice.lock);
        return -EINVAL;
    }
    s_voice.state = VOICE_STOPPING;
    audio_capture_t* cap = s_voice.cap;
    pthread_mutex_unlock(&s_voice.lock);

    /* Stop DMA first so a blocked capture read wakes up before join(). */
    if (cap) {
        audio_capture_stop(cap);
    }

    /* Wait for recording thread to finish */
    pthread_join(s_voice.rec_thread, NULL);

    /* Close capture device */
    audio_capture_close(cap);

    pthread_mutex_lock(&s_voice.lock);
    s_voice.cap = NULL;
    size_t pcm_len = s_voice.pcm_len;
    unsigned char* pcm_buf = s_voice.pcm_buf;
    s_voice.pcm_buf = NULL;
    voice_asr_stream_t* stream = s_voice.asr_stream;
    s_voice.asr_stream = NULL;
    s_voice.state = VOICE_IDLE;
    pthread_mutex_unlock(&s_voice.lock);

    syslog(LOG_INFO, "[%s] recorded %zu bytes\n", TAG, pcm_len);
    printf("Voice: recorded %zu bytes, sending to ASR...\n", pcm_len);

    /* A stream can have valid audio even though pcm_len is not used by the
     * stream completion path. Only abort it when there was no stream. */
    if (stream) {
        char text[512];
        int ret = voice_asr_stream_finish(stream, text,
            sizeof(text));

        free(pcm_buf);

        if (ret == 0 && text[0] != '\0') {
            syslog(LOG_INFO, "[%s] stream ASR: %s\n", TAG, text);
            printf("ASR: %s\n", text);

            velaclaw_msg_t msg;

            memset(&msg, 0, sizeof(msg));
            strncpy(msg.channel, VELACLAW_CHAN_VOICE,
                sizeof(msg.channel) - 1);
            strncpy(msg.chat_id, "voice",
                sizeof(msg.chat_id) - 1);
            msg.content = strdup(text);
            if (msg.content) {
                message_bus_push_inbound(&msg);
            }
        } else {
            syslog(LOG_WARNING,
                "[%s] stream ASR failed: %d\n", TAG, ret);
        }
