    43	static size_t url_encode(const char *src, char *dst, size_t dst_size)
    44	{
    45	    static const char hex[] = "0123456789ABCDEF";
    46	    size_t pos = 0;
    47	    if (dst_size == 0) return 0;
    48	    for (; *src && pos < dst_size - 3; src++) {
    49	        unsigned char c = (unsigned char)*src;
    50	        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
    51	            (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~') {
    52	            dst[pos++] = c;
    53	        } else if (c == ' ') {
    54	            dst[pos++] = '+';
    55	        } else {
    56	            dst[pos++] = '%';
    57	            dst[pos++] = hex[c >> 4];
    58	            dst[pos++] = hex[c & 0x0F];
    59	        }
    60	    }
    61	    dst[pos] = '\0';
    62	    return pos;
    63	}
