   568	 * get_weather tool
   569	 *   Input JSON: { "location": "Shanghai" }
   570	 *   Backends: wttr.in → Tavily → SerpAPI
   571	 * ──────────────────────────────────────────────────────────────*/
   572	
   573	static int wttr_weather(const char *location, char *output,
   574	                        size_t output_size)
   575	{
   576	    char encoded[256];
   577	    char path[320];
   578	    char *buf;
   579	    int status;
   580	
   581	    url_encode_path(location, encoded, sizeof(encoded));
   582	    if (encoded[0] == '\0') {
   583	        return ERROR;
   584	    }
   585	
   586	    snprintf(path, sizeof(path), "/%s?format=j1&lang=en", encoded);
   587	
   588	    buf = calloc(1, SEARCH_BUF_SIZE);
   589	    if (!buf) {
   590	        return ERROR;
   591	    }
   592	
   593	    vela_header_t hdrs[] = {
   594	        { "Accept", "application/json" },
   595	        { "User-Agent", "velaclaw/1.0" },
   596	        { NULL, NULL }
   597	    };
   598	
   599	    status = https_get_json("wttr.in", path, hdrs, buf, SEARCH_BUF_SIZE);
   600	    if (status != 200) {
   601	        syslog(LOG_WARNING, "[%s] wttr.in returned HTTP %d\n",
   602	               TAG, status);
   603	        free(buf);
   604	        return ERROR;
   605	    }
   606	
   607	    cJSON *root = cJSON_Parse(buf);
   608	    free(buf);
   609	    if (!root) {
   610	        syslog(LOG_WARNING, "[%s] wttr.in response was not JSON\n", TAG);
   611	        return ERROR;
   612	    }
   613	
   614	    cJSON *current = cJSON_GetObjectItem(root, "current_condition");
   615	    cJSON *condition = cJSON_IsArray(current) && cJSON_GetArraySize(current) > 0
   616	        ? cJSON_GetArrayItem(current, 0) : NULL;
   617	    cJSON *desc = condition ? cJSON_GetObjectItem(condition, "weatherDesc") : NULL;
   618	    cJSON *desc_item = cJSON_IsArray(desc) && cJSON_GetArraySize(desc) > 0
   619	        ? cJSON_GetArrayItem(desc, 0) : NULL;
   620	    cJSON *desc_value = desc_item
   621	        ? cJSON_GetObjectItem(desc_item, "value") : NULL;
   622	    cJSON *temp = condition
   623	        ? cJSON_GetObjectItem(condition, "temp_C") : NULL;
   624	    cJSON *feels = condition
   625	        ? cJSON_GetObjectItem(condition, "FeelsLikeC") : NULL;
   626	    cJSON *humidity = condition
   627	        ? cJSON_GetObjectItem(condition, "humidity") : NULL;
   628	    cJSON *wind = condition
   629	        ? cJSON_GetObjectItem(condition, "windspeedKmph") : NULL;
   630	
   631	    if (!condition || !desc_value || !cJSON_IsString(desc_value) ||
   632	        !temp || !cJSON_IsString(temp) ||
   633	        !feels || !cJSON_IsString(feels) ||
   634	        !humidity || !cJSON_IsString(humidity) ||
   635	        !wind || !cJSON_IsString(wind)) {
   636	        cJSON_Delete(root);
   637	        return ERROR;
   638	    }
   639	
   640	    snprintf(output, output_size,
   641	             "Weather for %s: %s, %s C, feels like %s C, humidity %s%%, "
   642	             "wind %s km/h.",
   643	             location, desc_value->valuestring, temp->valuestring,
   644	             feels->valuestring, humidity->valuestring, wind->valuestring);
   645	    cJSON_Delete(root);
   646	    return output[0] != '\0' ? OK : ERROR;
   647	}
