int voice_channel_start(void)
{
    pthread_mutex_lock(&s_voice.lock);
    if (s_voice.state != VOICE_IDLE) {
        pthread_mutex_unlock(&s_voice.lock);
        syslog(LOG_WARNING, "[%s] already recording\n", TAG);
        return -EBUSY;
    }

    /* Keep a bounded copy so a failed streaming session can fall back to
     * batch ASR without losing the audio already sent to the server. */
    s_voice.pcm_cap = VELACLAW_VOICE_PCM_BUF_SIZE;
    s_voice.pcm_buf = malloc(s_voice.pcm_cap);
    if (!s_voice.pcm_buf) {
        pthread_mutex_unlock(&s_voice.lock);
        syslog(LOG_ERR, "[%s] PCM buffer allocation failed\n", TAG);
        return -ENOMEM;
    }
    s_voice.pcm_len = 0;
    s_voice.asr_stream = NULL;

    /* Open capture device */
    s_voice.cap = audio_capture_open(
        VELACLAW_AUDIO_CAPTURE_DEV,
        VELACLAW_VOICE_SAMPLE_RATE,
        VELACLAW_VOICE_CHANNELS,
        VELACLAW_VOICE_BITS);

    if (!s_voice.cap) {
        pthread_mutex_unlock(&s_voice.lock);
        syslog(LOG_ERR, "[%s] capture open failed\n", TAG);
        return -EIO;
    }

    if (audio_capture_start(s_voice.cap) < 0) {
        audio_capture_close(s_voice.cap);
        s_voice.cap = NULL;
        pthread_mutex_unlock(&s_voice.lock);
        return -EIO;
    }

    s_voice.state = VOICE_RECORDING;
    pthread_mutex_unlock(&s_voice.lock);

    /* Spawn recording thread */
    pthread_attr_t attr;

    pthread_attr_init(&attr);
    pthread_attr_setstacksize(&attr, VELACLAW_VOICE_STACK);

    int ret = pthread_create(&s_voice.rec_thread, &attr,
        recording_thread, NULL);

    pthread_attr_destroy(&attr);

    if (ret != 0) {
        pthread_mutex_lock(&s_voice.lock);
        s_voice.state = VOICE_IDLE;
        audio_capture_close(s_voice.cap);
        s_voice.cap = NULL;
        free(s_voice.pcm_buf); /* may be NULL, free(NULL) is safe */
        s_voice.pcm_buf = NULL;
        pthread_mutex_unlock(&s_voice.lock);
        return -ret;
    }

    syslog(LOG_INFO, "[%s] PTT recording started\n", TAG);
    printf("Voice: recording... (use voice_stop to finish)\n");
    return 0;
}

int voice_channel_stop(void)
{
    pthread_mutex_lock(&s_voice.lock);
    if (s_voice.state != VOICE_RECORDING) {
        pthread_mutex_unlock(&s_voice.lock);
        return -EINVAL;
    }
    s_voice.state = VOICE_STOPPING;
    audio_capture_t* cap = s_voice.cap;
    pthread_mutex_unlock(&s_voice.lock);

    /* Stop DMA first so a blocked capture read wakes up before join(). */
    if (cap) {
        audio_capture_stop(cap);
    }

    /* Wait for recording thread to finish */
    pthread_join(s_voice.rec_thread, NULL);

    /* Close capture device */
    audio_capture_close(cap);

    pthread_mutex_lock(&s_voice.lock);
    s_voice.cap = NULL;
    size_t pcm_len = s_voice.pcm_len;
    unsigned char* pcm_buf = s_voice.pcm_buf;
    s_voice.pcm_buf = NULL;
    voice_asr_stream_t* stream = s_voice.asr_stream;
    s_voice.asr_stream = NULL;
    s_voice.state = VOICE_IDLE;
    pthread_mutex_unlock(&s_voice.lock);

    syslog(LOG_INFO, "[%s] recorded %zu bytes\n", TAG, pcm_len);
    printf("Voice: recorded %zu bytes, sending to ASR...\n", pcm_len);

    /* A stream can have valid audio even though pcm_len is not used by the
     * stream completion path. Only abort it when there was no stream. */
    if (stream) {
        char text[512];
        int ret = voice_asr_stream_finish(stream, text,
            sizeof(text));

        free(pcm_buf);

        if (ret == 0 && text[0] != '\0') {
            syslog(LOG_INFO, "[%s] stream ASR: %s\n", TAG, text);
            printf("ASR: %s\n", text);

            velaclaw_msg_t msg;

            memset(&msg, 0, sizeof(msg));
            strncpy(msg.channel, VELACLAW_CHAN_VOICE,
                sizeof(msg.channel) - 1);
            strncpy(msg.chat_id, "voice",
                sizeof(msg.chat_id) - 1);
            msg.content = strdup(text);
            if (msg.content) {
                message_bus_push_inbound(&msg);
                message_bus_push_inbound(&msg);
            }
        } else {
            syslog(LOG_WARNING,
                "[%s] stream ASR failed: %d\n", TAG, ret);
        }
        return 0;
    }

    if (pcm_len == 0) {
        free(pcm_buf);
        return 0;
    }

    /* Batch fallback: pcm_buf must exist if we reach here */
    if (!pcm_buf) {
        syslog(LOG_ERR, "[%s] no PCM data for batch ASR\n", TAG);
        return -ENODATA;
    }

    /* Batch fallback: pack pcm_len + audio for ASR thread */
    size_t total = sizeof(size_t) + pcm_len;
    unsigned char* pkg = malloc(total);

    if (!pkg) {
        free(pcm_buf);
        return -ENOMEM;
    }

    memcpy(pkg, &pcm_len, sizeof(size_t));
    memcpy(pkg + sizeof(size_t), pcm_buf, pcm_len);
    free(pcm_buf);

    /* Spawn ASR worker thread */
    int ret = velaclaw_task_create(asr_and_dispatch, "asr_worker",
        ASR_THREAD_STACK, pkg, VELACLAW_VOICE_PRIO);

    if (ret != OK) {
        free(pkg);
        return -EIO;
    }

    return 0;
}

