static int write_pcm_file(const char* path,
    const unsigned char* data, size_t len)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    size_t off = 0;

    if (fd < 0) {
        syslog(LOG_ERR, "[%s] Cannot create %s: %d\n",
            TAG, path, errno);
        return -errno;
    }

    while (off < len) {
        ssize_t nw = write(fd, data + off, len - off);
        if (nw < 0) {
            if (errno == EINTR) {
                continue;
            }
            close(fd);
            return -errno;
        }
        if (nw == 0) {
            close(fd);
            return -EIO;
        }
        off += (size_t)nw;
    }

    close(fd);
    return 0;
}

