            syslog(LOG_INFO, "[%s] News via Tavily OK: %d bytes\n", TAG, (int)strlen(output));
            return OK;
        }
        syslog(LOG_WARNING, "[%s] Tavily news failed, trying NewsAPI\n", TAG);
    }

