/* ──────────────────────────────────────────────────────────────
 * get_weather tool
 *   Input JSON: { "location": "Shanghai" }
 *   Backends: wttr.in → Tavily → SerpAPI
 * ──────────────────────────────────────────────────────────────*/

static int wttr_weather(const char *location, char *output,
                        size_t output_size)
{
    char encoded[256];
    char path[320];
    char *buf;
    int status;

    url_encode_path(location, encoded, sizeof(encoded));
    if (encoded[0] == '\0') {
        return ERROR;
    }

    snprintf(path, sizeof(path), "/%s?format=j1&lang=en", encoded);

    buf = calloc(1, SEARCH_BUF_SIZE);
    if (!buf) {
        return ERROR;
    }

    vela_header_t hdrs[] = {
        { "Accept", "application/json" },
        { "User-Agent", "velaclaw/1.0" },
        { NULL, NULL }
    };

    status = https_get_json("wttr.in", path, hdrs, buf, SEARCH_BUF_SIZE);
    if (status != 200) {
        syslog(LOG_WARNING, "[%s] wttr.in returned HTTP %d\n",
               TAG, status);
        free(buf);
        return ERROR;
    }

    cJSON *root = cJSON_Parse(buf);
    free(buf);
    if (!root) {
        syslog(LOG_WARNING, "[%s] wttr.in response was not JSON\n", TAG);
        return ERROR;
    }

    cJSON *current = cJSON_GetObjectItem(root, "current_condition");
    cJSON *condition = cJSON_IsArray(current) && cJSON_GetArraySize(current) > 0
        ? cJSON_GetArrayItem(current, 0) : NULL;
    cJSON *desc = condition ? cJSON_GetObjectItem(condition, "weatherDesc") : NULL;
    cJSON *desc_item = cJSON_IsArray(desc) && cJSON_GetArraySize(desc) > 0
        ? cJSON_GetArrayItem(desc, 0) : NULL;
    cJSON *desc_value = desc_item
        ? cJSON_GetObjectItem(desc_item, "value") : NULL;
    cJSON *temp = condition
        ? cJSON_GetObjectItem(condition, "temp_C") : NULL;
    cJSON *feels = condition
        ? cJSON_GetObjectItem(condition, "FeelsLikeC") : NULL;
    cJSON *humidity = condition
        ? cJSON_GetObjectItem(condition, "humidity") : NULL;
    cJSON *wind = condition
        ? cJSON_GetObjectItem(condition, "windspeedKmph") : NULL;

    if (!condition || !desc_value || !cJSON_IsString(desc_value) ||
        !temp || !cJSON_IsString(temp) ||
        !feels || !cJSON_IsString(feels) ||
        !humidity || !cJSON_IsString(humidity) ||
        !wind || !cJSON_IsString(wind)) {
        cJSON_Delete(root);
        return ERROR;
    }

    snprintf(output, output_size,
             "Weather for %s: %s, %s C, feels like %s C, humidity %s%%, "
             "wind %s km/h.",
             location, desc_value->valuestring, temp->valuestring,
             feels->valuestring, humidity->valuestring, wind->valuestring);
    cJSON_Delete(root);
    return output[0] != '\0' ? OK : ERROR;
}

