static int write_pcm_file(const char* path,
    const unsigned char* data, size_t len)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    size_t off = 0;

    if (fd < 0) {
        syslog(LOG_ERR, "[%s] Cannot create %s: %d\n",
            TAG, path, errno);
        return -errno;
    }

    while (off < len) {
        ssize_t nw = write(fd, data + off, len - off);
        if (nw < 0) {
            if (errno == EINTR) {
                continue;
            }
            close(fd);
            return -errno;
        }
        if (nw == 0) {
            close(fd);
            return -EIO;
        }
        off += (size_t)nw;
    }

    close(fd);
    return 0;
}

#define ASR_THREAD_STACK (24 * 1024)

static void* asr_and_dispatch(void* arg);

static int dispatch_batch_asr(unsigned char* pcm_buf, size_t pcm_len)
{
    size_t total;
    unsigned char* pkg;
    int ret;

    if (!pcm_buf || pcm_len == 0) {
        free(pcm_buf);
        return 0;
    }

    total = sizeof(size_t) + pcm_len;
    pkg = malloc(total);
    if (!pkg) {
        free(pcm_buf);
        return -ENOMEM;
    }

    memcpy(pkg, &pcm_len, sizeof(size_t));
    memcpy(pkg + sizeof(size_t), pcm_buf, pcm_len);
    free(pcm_buf);

    ret = velaclaw_task_create(asr_and_dispatch, "asr_worker",
        ASR_THREAD_STACK, pkg, VELACLAW_VOICE_PRIO);
    if (ret != OK) {
        free(pkg);
        return -EIO;
    }

    return 0;
}

/* ── Recording thread (PTT mode — streaming ASR) ─────────── */

static void* recording_thread(void* arg)
{
    (void)arg;
    unsigned char chunk[VELACLAW_ASR_CHUNK_SIZE];

    syslog(LOG_INFO, "[%s] recording thread started (streaming)\n",
        TAG);

    /* Open streaming ASR session */
    voice_asr_stream_t* stream = voice_asr_stream_open();

    if (!stream) {
        syslog(LOG_WARNING,
            "[%s] streaming ASR unavailable, batch fallback\n",
            TAG);
    }

    while (1) {
        pthread_mutex_lock(&s_voice.lock);
        enum voice_state st = s_voice.state;
        pthread_mutex_unlock(&s_voice.lock);

        if (st != VOICE_RECORDING) {
            break;
        }

        int n = audio_capture_read(s_voice.cap, chunk, sizeof(chunk));

        if (n <= 0) {
            break;
        }

        /*
         * Keep the complete utterance while streaming. If the network stream
         * fails halfway through, batch fallback must include the audio sent
         * before the failure as well.
         */
        pthread_mutex_lock(&s_voice.lock);
        if (s_voice.pcm_buf &&
            s_voice.pcm_len + (size_t)n <= s_voice.pcm_cap) {
            memcpy(s_voice.pcm_buf + s_voice.pcm_len, chunk, n);
            s_voice.pcm_len += n;
        }
        pthread_mutex_unlock(&s_voice.lock);

        /* Stream chunk to ASR server */
        if (stream) {
            int ret = voice_asr_stream_send(stream,
                chunk, (size_t)n);
            if (ret != 0) {
                syslog(LOG_ERR,
                    "[%s] stream send failed: %d, batch fallback\n",
                    TAG, ret);
                voice_asr_stream_abort(stream);
                stream = NULL;
            }
        }
    }

    /* Store stream handle for voice_channel_stop to finish */
    pthread_mutex_lock(&s_voice.lock);
    s_voice.asr_stream = stream;
    pthread_mutex_unlock(&s_voice.lock);

    syslog(LOG_INFO, "[%s] recording thread exiting\n", TAG);
    return NULL;
}

/* ── ASR worker thread ──────────────────────────────────── */

static void* asr_and_dispatch(void* arg)
{
    unsigned char* pcm = (unsigned char*)arg;
    size_t pcm_len;

    /* pcm_len is stored in the first sizeof(size_t) bytes */
    memcpy(&pcm_len, pcm, sizeof(size_t));
    const unsigned char* audio = pcm + sizeof(size_t);

    syslog(LOG_INFO, "[%s] ASR: recognizing %zu bytes\n",
        TAG, pcm_len);

    char text[512];
    int ret = voice_asr_recognize(audio, pcm_len,
        text, sizeof(text));

    if (ret == 0 && text[0] != '\0') {
        syslog(LOG_INFO, "[%s] ASR result: %s\n", TAG, text);
        printf("ASR: %s\n", text);

        velaclaw_msg_t msg;

        memset(&msg, 0, sizeof(msg));
        strncpy(msg.channel, VELACLAW_CHAN_VOICE,
            sizeof(msg.channel) - 1);
        strncpy(msg.chat_id, "voice",
            sizeof(msg.chat_id) - 1);
        msg.content = strdup(text);
        if (msg.content) {
            message_bus_push_inbound(&msg);
        }
    } else {
        syslog(LOG_WARNING, "[%s] ASR failed or empty: %d\n",
            TAG, ret);
    }

    free(pcm);
    return NULL;
}

