   164	/* ──────────────────────────────────────────────────────────────
   165	 * Backend 1: Tavily AI Search (primary — fast TLS)
   166	 *   POST https://api.tavily.com/search
   167	 *   Body: { "api_key":"...", "query":"...", "max_results":5 }
   168	 *   Response: { "results": [{ "title","url","content" }] }
   169	 * ──────────────────────────────────────────────────────────────*/
   170	
   171	static int tavily_search(const char *query, char *output, size_t output_size)
   172	{
   173	    cJSON *body_obj = cJSON_CreateObject();
   174	    cJSON_AddStringToObject(body_obj, "api_key", s_tavily_key);
   175	    cJSON_AddStringToObject(body_obj, "query", query);
   176	    cJSON_AddNumberToObject(body_obj, "max_results", SEARCH_RESULT_COUNT);
   177	    char *body_str = cJSON_PrintUnformatted(body_obj);
   178	    cJSON_Delete(body_obj);
   179	    if (!body_str) return ERROR;
   180	
   181	    vela_header_t hdrs[] = {
   182	        { "Content-Type", "application/json" },
   183	        { NULL, NULL }
   184	    };
   185	
   186	    char *buf = calloc(1, SEARCH_BUF_SIZE);
   187	    if (!buf) { free(body_str); return ERROR; }
   188	
   189	    int status = https_post_json("api.tavily.com", "/search", hdrs, body_str, buf, SEARCH_BUF_SIZE);
   190	    free(body_str);
   191	
   192	    if (status != 200) {
   193	        syslog(LOG_ERR, "[%s] Tavily returned HTTP %d: %.200s\n", TAG, status, buf);
   194	        free(buf);
   195	        return ERROR;
   196	    }
   197	
   198	    cJSON *root = cJSON_Parse(buf);
   199	    free(buf);
   200	    if (!root) return ERROR;
   201	
   202	    cJSON *results = cJSON_GetObjectItem(root, "results");
   203	    if (!results || !cJSON_IsArray(results) || cJSON_GetArraySize(results) == 0) {
   204	        snprintf(output, output_size, "No results found.");
