   210	    int idx = 0;
   211	    cJSON *item;
   212	    cJSON_ArrayForEach(item, results) {
   213	        if (idx >= SEARCH_RESULT_COUNT) break;
   214	        cJSON *title   = cJSON_GetObjectItem(item, "title");
   215	        cJSON *url     = cJSON_GetObjectItem(item, "url");
   216	        cJSON *content = cJSON_GetObjectItem(item, "content");
