   343	int audio_capture_read(audio_capture_t *cap, void *buf, size_t len)
   344	{
   345	  size_t copied = 0;
   346	  unsigned int waited_us = 0;
   347	
   348	  if (cap == NULL || buf == NULL || len == 0) {
   349	    return -EINVAL;
   350	  }
   351	
   352	  while (copied < len) {
   353	    size_t available;
   354	
   355	    if (cap->read_pending) {
   356	      available = cap->period_bytes - cap->read_offset;
   357	      if (available > len - copied) {
   358	        available = len - copied;
   359	      }
   360	      memcpy((unsigned char *)buf + copied,
   361	             cap->read_buf + cap->read_offset, available);
   362	      cap->read_offset += available;
   363	      copied += available;
   364	      if (cap->read_offset == cap->period_bytes) {
   365	        cap->read_offset = 0;
   366	        cap->read_pending = false;
   367	      }
   368	      continue;
   369	    }
   370	
   371	    if (!cap->started) {
   372	      return copied > 0 ? (int)copied : -EPIPE;
   373	    }
   374	
   375	    {
   376	      uint32_t slot = cap->next_read_slot % CAP_BUFFER_PERIODS;
   377	      uint32_t ready = cap->ready[slot];
   378	      uint32_t consumed = cap->consumed[slot];
   379	
   380	      if (ready != consumed) {
   381	        if (ready - consumed > 1) {
   382	          /* The reader fell behind; keep the newest complete period. */
   383	          consumed = ready - 1;
   384	          cap->consumed[slot] = consumed;
   385	          syslog(LOG_WARNING,
   386	                 "[%s] capture overrun, dropping old period\n", TAG);
   387	        }
   388	
   389	        up_invalidate_dcache(
   390	            (uintptr_t)(cap->dma_buf + slot * cap->period_bytes),
   391	            (uintptr_t)(cap->dma_buf + (slot + 1) * cap->period_bytes));
   392	        memcpy(cap->read_buf,
   393	               cap->dma_buf + slot * cap->period_bytes,
   394	               cap->period_bytes);
   395	        cap->consumed[slot] = consumed + 1;
   396	        cap->next_read_slot++;
   397	        cap->read_pending = true;
   398	        waited_us = 0;
   399	        continue;
   400	      }
   401	    }
   402	
   403	    if (waited_us >= CAP_WAIT_TIMEOUT_US) {
   404	      syslog(LOG_ERR, "[%s] timeout waiting for DMIC period\n", TAG);
   405	      return copied > 0 ? (int)copied : -ETIMEDOUT;
   406	    }
   407	
   408	    usleep(CAP_POLL_US);
   409	    waited_us += CAP_POLL_US;
   410	  }
   411	
   412	  return (int)copied;
   413	}
