typedef struct {
    char* data;
    size_t len;
    size_t cap;
} resp_buf_t;

static int resp_buf_init(resp_buf_t* rb, size_t initial_cap)
{
    rb->data = calloc(1, initial_cap);
    if (!rb->data)
        return ERROR;
    rb->len = 0;
    rb->cap = initial_cap;
    return OK;
}

static int resp_buf_append(resp_buf_t* rb, const char* data, size_t len)
{
