  uint32_t buffer_bytes;
  uint32_t next_read_slot;
  volatile uint32_t next_write_slot;
  volatile uint32_t ready[CAP_BUFFER_PERIODS];
  uint32_t consumed[CAP_BUFFER_PERIODS];
