      pthread_mutex_unlock(&g_ai_lock);
      mbus_tap_unregister(UI_DEMO_AI_CHANNEL);
      pthread_mutex_lock(&g_ai_lock);
      g_ai.tap_registered = false;
    }
  pthread_mutex_unlock(&g_ai_lock);

