static void ui_demo_ai_feature_event(lv_event_t *event)
{
  intptr_t raw_index;
  size_t index;

  if (lv_event_get_code(event) != LV_EVENT_CLICKED)
    {
      return;
    }

  raw_index = (intptr_t)lv_event_get_user_data(event);
  if (raw_index < 0)
    {
      return;
