+static int write_all(int fd, const char *buf, size_t len)
+{
+    size_t off = 0;
+
+    while (off < len) {
+        ssize_t n = write(fd, buf + off, len - off);
+        if (n < 0) {
+            if (errno == EINTR) {
+                continue;
+            }
+            return ERROR;
+        }
+        if (n == 0) {
+            return ERROR;
+        }
+        off += (size_t)n;
+    }
